mapper.select:
SELECT sm.id, sm.shop_id, li.id AS listingId, si.name AS shopName, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name AS platformProductName, li.match_result, li.product_image_url, li.product_spec, li.product_packing, li.platform_update_time, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, sm.create_user_name, sm.create_time FROM sku_mapping sm LEFT JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND li.match_result=#{matchResult}
AND sm.shop_id IN
#{shopId}
AND sm.type =#{params.type}
AND li.platform_spu_no IN
#{platformSpuNoItem}
AND li.platform_sku_no IN
#{platformSkuNoItem}
AND li.platform_fn_sku IN
#{fnSkuItem}
AND sm.dict_platform IN
#{platform}
AND sm.product_sku_no IN
#{skuNo}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT sm.id, sm.shop_id, li.id AS listingId, si.name AS shopName, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name AS platformProductName, li.platform_sku_no AS sellerSkuNo, li.platform_sku_name AS sellerProductName, li.match_result, li.product_image_url, li.product_spec, li.product_packing, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.platform_update_time, sm.create_user_name, sm.create_time FROM sku_mapping sm LEFT JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.id IN
#{id}
AND sm.match_result=#{matchResult}
AND sm.type =#{params.type}
AND li.platform_spu_no IN
#{platformSpuNoItem}
AND li.platform_sku_no IN
#{platformSkuNoItem}
AND li.platform_fn_sku IN
#{fnSkuItem}
AND sm.shop_id IN
#{shopId}
AND sm.product_sku_no IN
#{skuNo}
AND sm.platform_dict IN
#{platform}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT li.match_result, count(sm.*) FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE AND li.is_deleted=FALSE
AND sm.type=#{params.type}
${permissionSql}
GROUP BY match_result

SELECT product_sku_id AS skuId, product_sku_no AS skuNo, platform_sku_no, platform_sku_name FROM sku_maping sm INNER JOIN shop_info si ON sm.shop_id=si.id and si.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire=FALSE AND si.customer_code=(SELECT code FROM customer_info WHERE id=#{params.customerId})
AND ( sm.product_sku_no ILIKE concat('%',#{params.no}::text,'%') OR sm.platform_sku_no ILIKE concat('%',#{params.no}::text,'%') )
AND (sm.product_sku_no IN
#{skuNo}
OR sm.platform_sku_no IN
#{skuNo}
)

SELECT sm.id, li.id AS listingId, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no AS warehouseSkuNo, li.platform_sku_name AS warehouseProductName, li.match_result, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, sm.warehouse_id, sm.warehouse_name, sm.create_user_name, sm.create_time, sm.dict_platform, sm.platform_name, sm.has_mapping_all FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND li.match_result=#{matchResult}
AND sm.warehouse_id IN
#{warehouseId}
AND sm.type =#{params.type}
AND li.platform_spu_no IN
#{platformSpuNoItem}
AND li.platform_sku_no IN
#{platformSkuNoItem}
AND li.platform_fn_sku IN
#{fnSkuItem}
AND sm.dict_platform IN
#{platform}
AND li.platform_sku_name ILIKE concat('%',#{params.warehouseProductName}::text,'%')
AND sm.product_name ILIKE concat('%',#{params.productName}::text,'%')
AND li.platform_sku_no IN
#{warehouseSkuNo}
AND sm.product_sku_no IN
#{productSkuNo}
AND sm.product_sku_id IN
#{skuId}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT sm.id, li.id AS listingId, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no AS warehouseSkuNo, li.platform_sku_name AS warehouseProductName, li.match_result, sm.warehouse_id, sm.warehouse_name, sm.create_user_name, sm.create_time, sm.platform_name, sm.has_mapping_all FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.id IN
#{id}
AND li.match_result=#{matchResult}
AND sm.warehouse_id IN
#{warehouseId}
AND sm.type =#{params.type}
AND li.platform_sku_name ILIKE concat('%',#{params.warehouseProductName}::text,'%')
AND sm.product_name ILIKE concat('%',#{params.productName}::text,'%')
AND li.platform_sku_no IN
#{warehouseSkuNo}
AND sm.product_sku_no IN
#{productSkuNo}
AND li.platform_spu_no IN
#{platformSpuNoItem}
AND sm.product_sku_id IN
#{skuId}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT li.id AS listingId, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name, li.type FROM listing_info li LEFT JOIN sku_mapping sm ON sm.listing_id = li.id AND li.is_deleted = FALSE WHERE sm.is_deleted = FALSE and sm.is_expire=FALSE
AND li.platform_sku_no IN
#{platformSkuNo}

SELECT li.id AS listingId, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no AS platformSkuNo, li.platform_sku_name AS platformProductName FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id = li.id AND li.is_deleted = FALSE WHERE sm.is_deleted = FALSE AND sm.is_expire=FALSE
AND li.platform_sku_no IN
#{platformSkuNo}
AND li.platform = #{params.platform} AND sm.dict_platform = #{params.platform}
AND li.match_result = #{params.matchResult}

SELECT DISTINCT sm.product_sku_id, sm.product_sku_no, sm.product_name, sm.warehouse_id, sm.warehouse_name, sm.dict_platform, li.platform_sku_no AS stockSku, li.platform_sku_name AS stockSkuName FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE AND sm.is_expire=FALSE WHERE sm.is_deleted=FALSE
AND sm.product_sku_id IN
#{productSkuId}

SELECT sm.id, sm.shop_id, sm.listing_id, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, sm.product_name, sm.type, sm.warehouse_id, sm.warehouse_name, sm.effective_time, sm.expire_time, sm.is_expire, sm.has_mapping_all, li.platform_sku_no, li.platform_sku_name, li.platform, li.match_result, li.product_image_url, li.product_spec, li.product_packing, li.platform_update_time, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE AND sm.is_expire=FALSE WHERE sm.is_deleted=FALSE
AND li.platform_sku_no IN
#{platformSkuNo}
AND sm.type =#{params.type}
AND li.platform = #{params.platform} AND sm.dict_platform = #{params.platform}
AND li.match_result = #{params.matchResult}
AND sm.shop_id IN
#{shopId}
AND sm.warehouse_id IN
#{warehouseId}
